/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CLAIM_ANOMALY_DETECTION
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 10 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_ANOMALY_DETECTION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_NO))) as HUB_CLAIM_HK
        , IS_ANOMALY_FOUND as ANOMALY_FOUND_INDICATOR
        , ANOMALY_TYPE as ANOMALY_TYPE_CODE
        , ANOMALY_TIMESTAMP as ANOMALY_DETECTED_TIMESTAMP
        , ANOMALY_SUB_TYPE as ANOMALY_SUB_TYPE_CODE
        , DOC_CLASS as DOCUMENT_CLASS_EXAMINED
        , ANOMALY_DESCRIPTION as ANOMALY_DESCRIPTION
        , ANOMALY_SUPPORTING_DOC as ANOMALY_SUPPORTING_DOCUMENT_URI
        , BY_PASS_REMARKS as BYPASS_REMARKS
        , BY_PASS_REMARKS_UPDATED_ON as BYPASS_DECISION_TIMESTAMP
        , BY_PASS_REMARKS_BY as BYPASS_AUTHORISED_BY_USER_REFERENCE
        , 'BJAZ_BFHL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bfhl_dtls') }}
    where (nullif(trim(CLAIM_NO),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_FOUND_INDICATOR end) as ANOMALY_FOUND_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_TYPE_CODE end) as ANOMALY_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_DETECTED_TIMESTAMP end) as ANOMALY_DETECTED_TIMESTAMP,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_SUB_TYPE_CODE end) as ANOMALY_SUB_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then DOCUMENT_CLASS_EXAMINED end) as DOCUMENT_CLASS_EXAMINED,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_DESCRIPTION end) as ANOMALY_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then ANOMALY_SUPPORTING_DOCUMENT_URI end) as ANOMALY_SUPPORTING_DOCUMENT_URI,
        max(case when SOURCE_RUN = 'opus_health_v2' then BYPASS_REMARKS end) as BYPASS_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then BYPASS_DECISION_TIMESTAMP end) as BYPASS_DECISION_TIMESTAMP,
        max(case when SOURCE_RUN = 'opus_health_v2' then BYPASS_AUTHORISED_BY_USER_REFERENCE end) as BYPASS_AUTHORISED_BY_USER_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when ANOMALY_FOUND_INDICATOR is not null or ANOMALY_TYPE_CODE is not null or ANOMALY_DETECTED_TIMESTAMP is not null or ANOMALY_SUB_TYPE_CODE is not null or DOCUMENT_CLASS_EXAMINED is not null or ANOMALY_DESCRIPTION is not null or ANOMALY_SUPPORTING_DOCUMENT_URI is not null or BYPASS_REMARKS is not null or BYPASS_DECISION_TIMESTAMP is not null or BYPASS_AUTHORISED_BY_USER_REFERENCE is not null
                     then md5(upper(coalesce(cast(ANOMALY_FOUND_INDICATOR as varchar), '') || '|' || coalesce(cast(ANOMALY_TYPE_CODE as varchar), '') || '|' || coalesce(cast(ANOMALY_DETECTED_TIMESTAMP as varchar), '') || '|' || coalesce(cast(ANOMALY_SUB_TYPE_CODE as varchar), '') || '|' || coalesce(cast(DOCUMENT_CLASS_EXAMINED as varchar), '') || '|' || coalesce(cast(ANOMALY_DESCRIPTION as varchar), '') || '|' || coalesce(cast(ANOMALY_SUPPORTING_DOCUMENT_URI as varchar), '') || '|' || coalesce(cast(BYPASS_REMARKS as varchar), '') || '|' || coalesce(cast(BYPASS_DECISION_TIMESTAMP as varchar), '') || '|' || coalesce(cast(BYPASS_AUTHORISED_BY_USER_REFERENCE as varchar), '')))
                end as SAT_CLAIM_ANOMALY_DETECTION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_ANOMALY_DETECTION_HASHDIFF is not null
